# 
# Nothing here is examinable. It is here because the answer to "but where does
# that number actually come from?" is worth having written down.
# 
memclinic <- read.csv("data/memclinic.csv")
memclinic$group <- factor(memclinic$group, levels = c("HC", "MCI", "AD"))

# 
# ---- Loops ---------------------------------------------------------------------
# 
for (g in levels(memclinic$group)) {
  m <- mean(memclinic$moca[memclinic$group == g])
  cat(g, "mean MoCA:", round(m, 1), "\n")
}

# 
# `while` repeats until a condition fails; `repeat` runs until you `break`:
# 
x <- 0
while (x < 3) { x <- x + 1 }
x

x <- 0
repeat { x <- x + 1; if (x == 3) break }
x

# 
# `next` skips the rest of one iteration, `break` leaves the loop entirely.
# 
# ---- Preallocate ---------------------------------------------------------------
# 
# Growing a vector inside a loop makes R copy the whole thing each time:
# 
out <- numeric(length(levels(memclinic$group)))   # room reserved up front
for (i in seq_along(levels(memclinic$group))) {
  g <- levels(memclinic$group)[i]
  out[i] <- mean(memclinic$moca[memclinic$group == g])
}
round(out, 1)

# 
# Note `seq_along()` rather than `1:length()`, for the reason given in the session
# 01 appendix.
# 
# ---- But you rarely need a loop ------------------------------------------------
# 
# Everything above is one line:
# 
round(tapply(memclinic$moca, memclinic$group, mean), 1)

# 
# In R a loop is usually a sign that a vectorised function exists and you have not
# found it yet.
# 
# ---- The apply family ----------------------------------------------------------
# 
vars <- c("age", "moca", "hippo_vol_mm3")

sapply(memclinic[, vars], mean)        # simplifies to a vector
sapply(memclinic[, vars], range)       # ... or a matrix
str(lapply(memclinic[, vars], mean))   # always a list

# 
# `Filter()` keeps the elements matching a test:
# 
names(Filter(is.numeric, memclinic))

# 
# And `do.call()` calls a function with a list of arguments — the idiom
# `do.call(rbind, list_of_data_frames)` stacks many tables into one:
# 
pieces <- lapply(levels(memclinic$group), function(g) {
  d <- memclinic[memclinic$group == g, ]
  data.frame(group = g, n = nrow(d), mean_moca = round(mean(d$moca), 1))
})
do.call(rbind, pieces)

# 
# ---- Pipes ---------------------------------------------------------------------
# 
# A pipe passes the thing on its left into the function on its right, so that a
# sequence of steps reads left to right instead of inside out.
# 
sqrt(mean(memclinic$moca))              # inside out

memclinic$moca |> mean() |> sqrt()      # native pipe, R 4.1+

# 
# The lecture slides teach `%>%` from **magrittr**, which is what the tidyverse
# uses and what you will see in `WinterBreakExercises.R`:
# 
# library(magrittr)
# memclinic$moca %>% mean %>% sqrt

# 
# The two behave the same for straightforward uses like these.
# 
# ---- Graphics, in more depth ---------------------------------------------------
# 
# ---- Colour and plotting characters --------------------------------------------
# 
plot(memclinic$hippo_vol_mm3, memclinic$stroop_cost_ms,
     pch  = 16,
     col  = c("steelblue", "darkorange", "firebrick")[memclinic$group],
     xlab = "Hippocampal volume (mm³)",
     ylab = "Stroop interference cost (ms)")

legend("topright",
       legend = levels(memclinic$group),
       col    = c("steelblue", "darkorange", "firebrick"),
       pch    = 16,
       bty    = "n")

# 
# Indexing a colour vector *by a factor* works because a factor is stored as the
# integers 1, 2, 3 — the trap from practical 2, used deliberately.
# 
# With many overlapping points, make them transparent:
# 
plot(memclinic$age, memclinic$rt_mean,
     pch = 16, col = adjustcolor("black", alpha.f = 0.3),
     xlab = "Age (years)", ylab = "Mean RT (ms)")
abline(lm(rt_mean ~ age, data = memclinic), col = "blue", lwd = 2)
abline(h = mean(memclinic$rt_mean), lty = 2)   # horizontal reference line

