# ---- Reshaping, the other ways -------------------------------------------------
# 
# `reshape()` leaves a note to itself about how it reshaped, which lets it go back:
# 
stroop <- read.csv("data/stroop-rm.csv")
long <- reshape(stroop, direction = "long",
                varying = c("rt_congruent", "rt_neutral", "rt_incongruent"),
                v.names = "rt", timevar = "condition",
                times = c("congruent", "neutral", "incongruent"), idvar = "id")

names(attributes(long))
head(reshape(long, direction = "wide"), 2)

# 
# The modern alternative is `tidyr`:
# 
long2 <- tidyr::pivot_longer(stroop,
                             cols      = starts_with("rt_"),
                             names_to  = "condition",
                             names_prefix = "rt_",
                             values_to = "rt")
head(long2, 3)
nrow(long2)

# 
# Easier to read, and the same 108 rows.
# 
# ---- `merge()`, in full --------------------------------------------------------
# 
small <- memclinic[, c("id", "group", "moca")]
merged <- merge(stroop, small, by = "id")
nrow(merged)

# 
# When the key columns have different names, or you want to keep unmatched rows:
# 
# merge(a, b, by.x = "patient_id", by.y = "id")
# merge(a, b, by = "id", all.x = TRUE)    # keep every row of a (a "left join")

# 
# If the key is duplicated on **both** sides, `merge()` returns every matching
# combination — and your dataset silently grows:
# 
a <- data.frame(id = c("P01", "P01"), visit = 1:2)
b <- data.frame(id = c("P01", "P01"), score = c(10, 20))
nrow(a); nrow(b)
nrow(merge(a, b, by = "id"))    # not 2

# 
# Two rows and two rows gave four. Always check `nrow()` before and after a merge.
# This is the most common way to corrupt a dataset without ever seeing an error.
# 
# ---- Locale, encoding, and Excel -----------------------------------------------
# 
# Sys.getlocale("LC_NUMERIC")

# 
# In much of Europe the decimal separator is a comma and CSV files use `;` as the
# field separator. `read.csv2()` expects exactly that:
# 
# read.csv("file.csv")    # 1,234.5  and  fields separated by ,
# read.csv2("file.csv")   # 1.234,5  and  fields separated by ;

# 
# This is the concrete reason for the warning in the codebook: open
# `memclinic.csv` in Excel on an Italian machine and it will offer to save it back
# with commas for decimals. Everything still *looks* like a number, and
# `read.csv()` will then read `20.3` as the text `"20,3"`.
# 
# ---- Writing data out ----------------------------------------------------------
# 
# write.csv(memclinic, "my-version.csv", row.names = FALSE)

# 
# `row.names = FALSE` matters. Without it R adds an unnamed first column of row
# numbers, which becomes a mysterious variable called `X` the next time anyone
# reads the file.
